 public static byte[] Build(CompensacionDocumentoDto d){const decimal w=842,h=595,m=34;var pages=new List<StringBuilder>();int idx=0,page=1;do{var s=new StringBuilder();Rect(s,0,0,w,h,"F4F7FA");Rect(s,m,28,w-m*2,h-56,"FFFFFF","D9E2EC");Water(s,"SIN MOVIMIENTO DE CAJA");Rect(s,m,485,w-m*2,82,"17345B");Rect(s,m,485,7,82,"2493D8");Text(s,"CONSTANCIA DE COMPENSACION",m+22,535,19,"FFFFFF",true);Text(s,$"{d.Numero}  |  Fecha {d.Fecha:dd/MM/yyyy}",m+22,513,9,"D9EAF8",false);Right(s,d.EstadoCodigo=="R"?"REVERTIDA":"APLICADA",w-m-18,535,9,d.EstadoCodigo=="R"?"FFC7C7":"BDEFD8",true);if(page==1){Text(s,"PERSONA",m+18,452,7,"64748B",true);Text(s,Cut(d.Persona,60),m+18,430,13,"172033",true);Text(s,$"Documento: {d.Documento}   |   Saldo a favor #{d.IdObligacion}: {d.Concepto}",m+18,410,8,"53657A",false);Metric(s,m+18,345,"SALDO A FAVOR",Money(d.ImporteObligacion),"17345B");Metric(s,m+205,345,"IMPORTE COMPENSADO",Money(d.ImporteAplicado),"156B4A");Metric(s,m+392,345,"CUOTAS AFECTADAS",d.CuotasAfectadas.ToString(),"17345B");Metric(s,m+579,345,"SALDO FAVOR ACTUAL",Money(d.SaldoFavorActual),"A85B00");Text(s,"APLICACION A PRESTAMOS",m+18,316,9,"17345B",true);}Rect(s,m+18,276,738,24,"EAF0F7","D7E0EA");Text(s,"PRESTAMO / CUOTA",m+28,285,7,"53657A",true);Text(s,"VENCIMIENTO",m+170,285,7,"53657A",true);Right(s,"SALDO ANTES",m+420,285,7,"53657A",true);Right(s,"INTERES",m+530,285,7,"53657A",true);Right(s,"CAPITAL",m+630,285,7,"53657A",true);Right(s,"APLICADO",m+746,285,7,"53657A",true);int y=252,line=0;while(idx<d.Detalle.Count&&line<8){var x=d.Detalle[idx++];Rect(s,m+18,y-6,738,25,line%2==0?"FFFFFF":"F7F9FC","EDF1F5");Text(s,$"#{x.IdPrestamo} / {x.NumCuota}",m+28,y+2,8,"172033",true);Text(s,x.FechaVencimiento.ToString("dd/MM/yyyy"),m+170,y+2,8,"334155",false);Right(s,Money(x.SaldoAntes),m+420,y+2,8,"334155",false);Right(s,Money(x.InteresAplicado),m+530,y+2,8,"A85B00",false);Right(s,Money(x.CapitalAplicado),m+630,y+2,8,"334155",false);Right(s,Money(x.ImporteAplicado),m+746,y+2,8,"156B4A",tr