 static void Metric(StringBuilder s,decimal x,decimal y,string l,string v,string c){Rect(s,x,y,174,51,"F6F8FB","DFE6EE");Text(s,l,x+10,y+31,7,"64748B",true);Text(s,v,x+10,y+11,12,c,true);}static void Water(StringBuilder s,string t){var c=Color("E8EEF4");s.AppendLine("q").AppendLine($"{N(c.r)} {N(c.g)} {N(c.b)} rg").AppendLine("0.707 0.707 -0.707 0.707 270 70 cm").AppendLine($"BT /F2 35 Tf 0 0 Td ({Escape(t)}) Tj ET Q");}static string Money(decimal v)=>"S/."+v.ToString("#,##0.00",CultureInfo.GetCultureInfo("en-US"));static string Cut(string v,int n)=>v.Length<=n?v:v[..(n-3)]+"...";
 static void Rect(StringBuilder s,decimal x,decimal y,decimal w,decimal h,string f,string? st=null){var a=Color(f);s.AppendLine("q").AppendLine($"{N(a.r)} {N(a.g)} {N(a.b)} rg");if(st!=null){var b=Color(st);s.AppendLine($"{N(b.r)} {N(b.g)} {N(b.b)} RG").AppendLine($"{N(x)} {N(y)} {N(w)} {N(h)} re B");}else s.AppendLine($"{N(x)} {N(y)} {N(w)} {N(h)} re f");s.AppendLine("Q");}static void Text(StringBuilder s,string v,decimal x,decimal y,decimal z,string c,bool b){var q=Color(c);s.AppendLine("BT").AppendLine($"{N(q.r)} {N(q.g)} {N(q.b)} rg").AppendLine($"/{(b?"F2":"F1")} {N(z)} Tf").AppendLine($"{N(x)} {N(y)} Td").AppendLine($"({Escape(v)}) Tj ET");}static void Right(StringBuilder s,string v,decimal r,decimal y,decimal z,string c,bool b)=>Text(s,v,r-v.Length*z*(b?.56m:.52m),y,z,c,b);static(decimal r,decimal g,decimal b)Color(string h)=>(int.Parse(h[..2],NumberStyles.HexNumber)/255m,int.Parse(h.Substring(2,2),NumberStyles.HexNumber)/255m,int.Parse(h.Substring(4,2),NumberStyles.HexNumber)/255m);static string N(decimal v)=>v.ToString("0.###",CultureInfo.InvariantCulture);static string Escape(string v)=>Remove(v).Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)");static string Remove(string v){var b=new StringBuilder();foreach(var c in v.Normalize(NormalizationForm.FormD))if(CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark&&c<=127)b.Append(c);return b.ToString();}
 static byte[] Doc(List<StringBuilder> p,decimal w,decimal h){var o=new SortedDictionary<int,string>();var ids=new List<int>();var n=3;var reg=3+p.Count*2;var bold=reg+1;o[1]="1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n";foreach(var x in p){int pi=n++,ci=n++;ids.Add(pi);var st=x.ToString();o[pi]=$"{pi} 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 {N(w)} {N(h)}] /Resources << /Font << /F1 {reg} 0 R /F2 {bold} 0 R >> >> /Contents {ci} 0 R >> endobj\n";o[ci]=$"{ci} 0 obj << /Length {Encoding.ASCII.GetByteCount(st)} >> stream\n{st}endstream endobj\n";}o[2]=$"2 0 obj << /Type /Pages /Kids [{string.Join(" ",ids.Select(x=>$"{x} 0 R"))}] /Count {p.Count} >> endobj\n";o[reg]=$"{reg} 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj\n";o[bold]=$"{bold} 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >> endobj\n";var s=new StringBuilder("%PDF-1.4\n");var off=new Dictionary<int,int>();foreach(var x in o){off[x.Key]=Encoding.ASCII.GetByteCount(s.ToString());s.Append(x.Value);}var xr=Encoding.ASCII.GetByteCount(s.ToString());var max=o.Keys.Max();s.AppendLine("xref").AppendLine($"0 {max+1}").AppendLine("0000000000 65535 f ");for(var i=1;i<=max;i++)s.AppendLine(off.TryGetValue(i,out var z)?$"{z:0000000000} 00000 n ":"0000000000 65535 f ");s.AppendLine("trailer").AppendLine($"<< /Size {max+1} /Root 1 0 R >>").AppendLine("startxref").AppendLine(xr.ToString()).AppendLine("%%EOF");return Encoding.ASCII.GetBytes(s.ToString());}
